// Stock session that opens page 27 and runs the same 12 edges, then saves.
// Compared with the candidate store, which also opened page 27 and committed
// two zones. The candidate value is not on this image.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_store_k1.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
const OUT = resolve('work/out/accept-store-k1.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const EDGES = [
  ['s1', 'down'], ['s1', 'up'], ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
try {
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-store-k1.jsonl',
    tag: 'accept-store-k1',
    candidate: false,
    help: true,
    rowLabel: true,
    nvramPath: 'work/out/nvram-accept-store-control.json',
    fatalShots: false,
    explanation: 'Stock control that opens page 27, leaves, and runs the 12 edges.',
    change: 'none',
    async drive(ctx) {
      const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
      const api = A(0x50ac4afe);
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(500);
      const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
      ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
      ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
      ctx.idle(500);
      ctx.press('menu');
      for (let i = 0; i < 20; i++) ctx.press('left');
      ctx.press('down');
      ctx.press('down');
      ctx.press('ok');
      const view = ctx.screen();
      emit({ record: 'page', texts: view.texts, highlight: view.highlight });
      for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
      if (ctx.s.screen() !== 'shooting') throw new Error('not shooting');
      for (const [k, d] of EDGES) {
        ctx.key(k, d);
        ctx.idle(600);
      }
      emit({ record: 'edges-done', screen: ctx.s.screen() });
    },
  });
  if (!result.ok) throw new Error(result.failed);
  emit({ record: 'done', ok: true });
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
